package com.dy.artisan3d.ui.screen.homeimport androidx.compose.foundation.Imageimport androidx.compose.foundation.basicMarqueeimport androidx.compose.foundation.layout.aspectRatioimport androidx.compose.foundation.layout.fillMaxSizeimport androidx.compose.foundation.layout.fillMaxWidthimport androidx.compose.foundation.layout.paddingimport androidx.compose.foundation.lazy.LazyColumnimport androidx.compose.material3.CenterAlignedTopAppBarimport androidx.compose.material3.ExperimentalMaterial3Apiimport androidx.compose.material3.MaterialThemeimport androidx.compose.material3.Scaffoldimport androidx.compose.material3.Textimport androidx.compose.material3.pulltorefresh.PullToRefreshBoximport androidx.compose.runtime.Composableimport androidx.compose.ui.Modifierimport androidx.compose.ui.layout.ContentScaleimport androidx.compose.ui.text.style.TextOverflowimport androidx.compose.ui.unit.dpimport artisan3d.composeapp.generated.resources.Resimport artisan3d.composeapp.generated.resources.banner_bgimport org.jetbrains.compose.resources.painterResource@OptIn(ExperimentalMaterial3Api::class)@Composablefun HomeContent(){    Scaffold(        modifier = Modifier.fillMaxSize(),        topBar = {            CenterAlignedTopAppBar(                title = {                    Text("Artisan3D")                }            )        }    ) {paddingValues ->        PullToRefreshBox(            modifier = Modifier.padding(paddingValues),            isRefreshing = false,            onRefresh = {}        ){            LazyColumn(modifier = Modifier.fillMaxSize()){                item {                    Image(                        painter = painterResource(Res.drawable.banner_bg),                        contentDescription = null,                        modifier = Modifier.fillMaxWidth().aspectRatio(16/9f),                        contentScale = ContentScale.Crop                    )                    Text(                        text = "Zamonaviy dunyo uchun noyob qo‘l mehnati dizaynlari Artisan3D",                        modifier = Modifier                            .fillMaxWidth() // Matn kenglikka yoyilishi uchun                            .basicMarquee(                                iterations = Int.MAX_VALUE, // Cheksiz aylanish                            ),                        maxLines = 1, // Marquee ishlashi uchun matn 1 qatorda bo'lishi shart                        style = MaterialTheme.typography.bodyLarge                    )                }            }        }    }}